CREATE TABLE IF NOT EXISTS trilha (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255));
CREATE TABLE IF NOT EXISTS aluno (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255), matricula VARCHAR(255) NOT NULL UNIQUE, turma VARCHAR(255), trilha_id BIGINT REFERENCES trilha(id), pontos INTEGER DEFAULT 0);
CREATE TABLE portal_school (id VARCHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL, accent VARCHAR(20) NOT NULL, logo TEXT NOT NULL);
ALTER TABLE aluno ADD COLUMN IF NOT EXISTS school_id VARCHAR(36) REFERENCES portal_school(id);
CREATE INDEX aluno_school_idx ON aluno(school_id);
CREATE TABLE portal_member (id VARCHAR(36) PRIMARY KEY, school_id VARCHAR(36) NOT NULL REFERENCES portal_school(id), name VARCHAR(200) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, role VARCHAR(20) NOT NULL, password_hash VARCHAR(512) NOT NULL, course_ids TEXT NOT NULL, class_ids TEXT NOT NULL);
CREATE TABLE portal_session (token_hash VARCHAR(64) PRIMARY KEY, member_id VARCHAR(36) NOT NULL REFERENCES portal_member(id), expires_at TIMESTAMP NOT NULL);
CREATE INDEX portal_session_member_idx ON portal_session(member_id);
CREATE TABLE portal_member_student (member_id VARCHAR(36) NOT NULL REFERENCES portal_member(id), student_id BIGINT NOT NULL REFERENCES aluno(id), PRIMARY KEY(member_id, student_id));
CREATE TABLE portal_guardian (id VARCHAR(36) PRIMARY KEY, school_id VARCHAR(36) NOT NULL REFERENCES portal_school(id), name VARCHAR(200) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(80) NOT NULL, relationship VARCHAR(100) NOT NULL);
CREATE TABLE portal_guardian_student (guardian_id VARCHAR(36) NOT NULL REFERENCES portal_guardian(id), student_id BIGINT NOT NULL REFERENCES aluno(id), PRIMARY KEY(guardian_id, student_id));
CREATE TABLE portal_invitation (code_hash VARCHAR(64) PRIMARY KEY, school_id VARCHAR(36) NOT NULL REFERENCES portal_school(id), email VARCHAR(254) NOT NULL, role VARCHAR(20) NOT NULL, expires_at TIMESTAMP NOT NULL, consumed_at TIMESTAMP);
CREATE TABLE portal_invitation_student (code_hash VARCHAR(64) NOT NULL REFERENCES portal_invitation(code_hash), student_id BIGINT NOT NULL REFERENCES aluno(id), PRIMARY KEY(code_hash, student_id));
CREATE TABLE portal_documents (school_id VARCHAR(36) NOT NULL REFERENCES portal_school(id), domain VARCHAR(32) NOT NULL, revision BIGINT NOT NULL DEFAULT 0, payload TEXT NOT NULL, PRIMARY KEY(school_id,domain));
CREATE TABLE portal_extra (id VARCHAR(36) PRIMARY KEY, school_id VARCHAR(36) NOT NULL REFERENCES portal_school(id), student_id BIGINT NOT NULL REFERENCES aluno(id), policy_id VARCHAR(128) NOT NULL, course_id VARCHAR(40) NOT NULL, class_id VARCHAR(60) NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL, due_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, payload TEXT NOT NULL);
CREATE INDEX portal_extra_scope_idx ON portal_extra(school_id,student_id,created_at);
CREATE TABLE portal_attempt (id VARCHAR(36) PRIMARY KEY, assignment_id VARCHAR(36) NOT NULL REFERENCES portal_extra(id), student_id BIGINT NOT NULL REFERENCES aluno(id), question_id VARCHAR(128) NOT NULL, started_at TIMESTAMP NOT NULL, answered_at TIMESTAMP, selected_option_id VARCHAR(32), correct BOOLEAN, seconds DOUBLE PRECISION, points DOUBLE PRECISION, UNIQUE(assignment_id,student_id,question_id));
CREATE TABLE public_question (id VARCHAR(128) PRIMARY KEY, course_id VARCHAR(40) NOT NULL, payload TEXT NOT NULL);
